<?php require __DIR__.'/../db.php'; $db=connect_db($config['db']); ensure_core_tables($db); $rows=$db->query('SELECT s.full_name,f.month_key,f.amount,f.paid_amount,f.status FROM fees f INNER JOIN students s ON s.id=f.student_id ORDER BY f.id DESC LIMIT 200')->fetchAll()?:[]; include __DIR__.'/../layout/header.php'; include __DIR__.'/../layout/sidebar.php'; ?>
<h3>Fee Report</h3><table class="table"><tr><th>Name</th><th>Month</th><th>Amount</th><th>Paid</th><th>Status</th></tr><?php foreach($rows as $r): ?><tr><td><?= h((string)$r['full_name']) ?></td><td><?= h((string)$r['month_key']) ?></td><td><?= h((string)$r['amount']) ?></td><td><?= h((string)$r['paid_amount']) ?></td><td><?= h((string)$r['status']) ?></td></tr><?php endforeach; ?></table>
